    canvas.getContext('2d').drawImage(video, 0, 0);

    // Set up a timer to capture a new image every few seconds
    setInterval(function() {
      // Draw the current frame from the video element onto the canvas
      canvas.getContext('2d').drawImage(video, 0, 0);

      // Get the image data from the canvas
      var data = canvas.toDataURL();

      // Send the image data to a server or use it for other purposes
      // For example, you could send it to a server for storage or analysis
    }, 5000); // Capture a new image every 5 seconds
  })
  .catch(function(error) {
    console.error('Error accessing webcam:', error);
  });
```

